        uint256 finalTotalRewards = fuckMaker.totalRewards();
        uint256 finalUserFucks = fuckMaker.userFucks(address(this));
        (, uint256 finalUserRewards) = fuckMaker.getUserStats(address(this));

        // Log AFTER-Trigger state
        emit log("--- AFTER-Trigger State ---");
        emit log_named_uint("Final totalFucksMade", finalTotalFucksMade);
        emit log_named_uint("Final totalRewards", finalTotalRewards);
        emit log_named_uint("Final userFucks", finalUserFucks);
