        (uint256 finalFucksMade, uint256 finalRewards) = fuckMaker.getUserStats(address(this));
        assertEq(finalFucksMade, initialFucksMade + 3, "FucksMade should increment");
        assertGt(finalRewards, initialUserRewards, "Rewards should not increment when calls fail");
    }
